"""The symbolic half of the neuro-symbolic model: explicit rules, in code, in plain words.

Two kinds of rule, and the difference matters:

* **HARD rules forbid.** They are safety and physics, checked with the robot's own models
  (`robot_model`), and no score from any network can overrule them. This is the guarantee a
  learned policy cannot give by itself: whatever the network prefers, the robot will not strand
  itself, cook its motors, overload itself or work when it needs maintenance.

* **PRIORITY rules rank.** A line that has already stopped outranks one that is merely full-ish;
  a line about to stop outranks a quiet one. The neural scorer then chooses WITHIN the top
  priority tier, which is where judgement (is this trip worth the energy? collect two sections in
  one trip?) actually lives.

Every verdict carries the reasons, so a decision can always be explained.
"""
from dataclasses import dataclass, field

from robofetch_core.mission_plan import CHARGE, CHARGER, DELIVER, PICKUP, WAIT
from robofetch_core.robot_model import RobotCondition, battery_percent_for, simulate_route

TIER_NAMES = {2: "unblock a stopped line", 1: "prevent a line from stopping", 0: "routine"}


@dataclass
class Verdict:
    allowed: bool = True
    tier: int = 0
    refusals: list = field(default_factory=list)   # why a hard rule forbids it
    reasons: list = field(default_factory=list)    # why it is (or is not) urgent

    def why(self):
        return "; ".join(self.refusals if not self.allowed else self.reasons) or "routine"


class SymbolicLayer:
    def __init__(self, cfg):
        ns = cfg["mission"]["neurosymbolic"]
        self.urgency_horizon_s = float(ns["urgency_horizon_s"])
        self.safety_margin = float(ns["safety_margin_percent"])

    # --------------------------------------------------------------------------- hard rules
    def check(self, state, action, p, matrix):
        """Apply every rule to one candidate action."""
        v = Verdict()
        location = state["location"]
        dest = action.destination()

        # H1 maintenance: a worn-out robot may only charge or wait.
        if state["condition_percent"] < p.condition_min_percent and action.kind in (PICKUP, DELIVER):
            v.allowed = False
            v.refusals.append(f"condition {state['condition_percent']:.0f} % is below the "
                              f"maintenance limit ({p.condition_min_percent:.0f} %)")

        # H2 payload: never plan to carry more than the limit.
        if action.kind == PICKUP and state["sections"][action.target]["units_that_fit"] <= 0:
            v.allowed = False
            v.refusals.append(f"nothing at {action.target} that still fits "
                              f"({state['payload_kg']:.1f} of {p.max_payload_kg:.1f} kg carried)")

        # H3 reserve: after this action the robot must still reach the charger with the reserve.
        if dest and action.kind != CHARGE:
            legs = [(matrix[location][dest], state["payload_kg"]),
                    (matrix[dest][CHARGER], state["payload_kg"] if action.kind == PICKUP else 0.0)]
            condition = RobotCondition(p, battery_percent=state["battery_percent"],
                                       temperature_c=state["temperature_c"],
                                       condition_percent=state["condition_percent"])
            end, peak = simulate_route(condition, legs,
                                       dwell_s=p.load_time_s if action.kind == PICKUP
                                       else p.unload_time_s)
            need = p.reserve_percent + self.safety_margin
            if end.battery_percent < need:
                v.allowed = False
                v.refusals.append(
                    f"battery would be {end.battery_percent:.0f} % back at the charger, below the "
                    f"{need:.0f} % reserve")
            # H4 heat: the motors must stay below their limit for the whole route.
            if peak >= p.max_c:
                v.allowed = False
                v.refusals.append(f"motors would reach {peak:.0f} C (limit {p.max_c:.0f} C)")

        if not v.allowed:
            return v

        # ------------------------------------------------------------------- priority rules
        if action.kind == PICKUP:
            section = state["sections"][action.target]
            travel_s = matrix[location][action.target] / p.speed_m_s
            if section["status"] == "BLOCKED":
                v.tier = 2
                v.reasons.append(f"{action.target} is BLOCKED and losing production")
            elif section["time_to_full_s"] <= max(self.urgency_horizon_s, travel_s):
                v.tier = 1
                v.reasons.append(f"{action.target} fills in {section['time_to_full_s']:.0f} s "
                                 f"({travel_s:.0f} s away)")
            else:
                v.reasons.append(f"{action.target} has {section['buffer_units']} units waiting")
        elif action.kind == DELIVER:
            if state["free_payload_kg"] <= 0.01:
                v.tier = 1
                v.reasons.append("the robot is full and cannot collect anything else")
            else:
                v.reasons.append(f"carrying {state['cargo_units']} units")
        elif action.kind == CHARGE:
            home_percent = battery_percent_for(
                p, p.idle_power_w * (matrix[location][CHARGER] / p.speed_m_s) / 3600.0)
            if state["battery_percent"] <= p.reserve_percent + home_percent + self.safety_margin:
                v.tier = 2
                v.reasons.append(f"battery {state['battery_percent']:.0f} % is at the reserve")
            else:
                v.reasons.append(f"top up from {state['battery_percent']:.0f} %")
        elif action.kind == WAIT:
            if state["location"] == CHARGER:
                v.reasons.append("waiting at the charger is free and tops the battery up")
            else:
                v.reasons.append("waiting away from the charger only spends energy")
        return v

    def evaluate(self, state, legal_actions, p, matrix):
        """{action: Verdict} for every legal action."""
        return {action: self.check(state, action, p, matrix) for action in legal_actions}

    @staticmethod
    def allowed_by_tier(verdicts):
        """The allowed actions of the highest priority tier, and that tier."""
        allowed = {a: v for a, v in verdicts.items() if v.allowed}
        if not allowed:
            return {}, None
        top = max(v.tier for v in allowed.values())
        return {a: v for a, v in allowed.items() if v.tier == top}, top

"""The decision service: the robot asks "what next?", a model answers.

    POST /decide   {model, scenario, state}   -> {action, explanation, scores, latency_ms, model}
    GET  /health                              -> which models are loaded and ready
    GET  /models                              -> the available decision models

It runs as a SEPARATE process on its own port, exactly as in the old project, and for the same
reason: "the AI is unavailable" has to be a state you can produce by stopping a process, so the
robot's fallback behaviour is testable rather than theoretical. The mission executor falls back to
its own built-in rule when this service does not answer.

The models here are the ones evaluated in the fast simulator - same code, same weights - so what
the thesis measures offline is what drives the robot.

    venv/bin/python -m uvicorn robofetch_ai.service:app --port 8001
"""
import math
import os
import time
import traceback

from fastapi import FastAPI
from pydantic import BaseModel

from robofetch_ai.env.live_state import LiveState

DEFAULT_SCENARIO = os.environ.get("ROBOFETCH_SCENARIO", "balanced")
MODELS = ("ns", "ns_symbolic_only", "ns_neural_only", "ppo", "rule")

app = FastAPI(title="RoboFetch decision service")
_contexts = {}          # scenario -> LiveState
_policies = {}          # (model, scenario) -> Policy
_stats = {"decisions": 0, "failures": 0}


class DecideRequest(BaseModel):
    state: dict
    model: str = "ns"
    scenario: str = DEFAULT_SCENARIO


def context(scenario):
    if scenario not in _contexts:
        _contexts[scenario] = LiveState(scenario)
    return _contexts[scenario]


def policy(name, scenario):
    """Built once and kept: loading a network on every request would cost more than deciding."""
    key = (name, scenario)
    if key not in _policies:
        cfg = context(scenario).cfg
        if name == "rule":
            from robofetch_ai.policies.rule_based import RuleBasedPolicy
            _policies[key] = RuleBasedPolicy()
        elif name.startswith("ns"):
            from robofetch_ai.policies.neurosymbolic import NeuroSymbolicPolicy
            mode = {"ns": "full", "ns_neural_only": "neural",
                    "ns_symbolic_only": "symbolic"}[name]
            _policies[key] = NeuroSymbolicPolicy(cfg, mode=mode)
        elif name == "ppo":
            from robofetch_ai.policies.rl_ppo import PPOPolicy
            _policies[key] = PPOPolicy(cfg)
        else:
            raise ValueError(f"unknown model '{name}', known: {', '.join(MODELS)}")
    return _policies[key]


def json_safe(value):
    """JSON has no infinity or NaN; a decision must still be reportable."""
    if isinstance(value, dict):
        return {k: json_safe(v) for k, v in value.items()}
    if isinstance(value, list):
        return [json_safe(v) for v in value]
    if isinstance(value, float) and not math.isfinite(value):
        return None
    return value


@app.get("/health")
def health():
    return {"ok": True, "loaded": [f"{m}/{s}" for m, s in _policies],
            "decisions": _stats["decisions"], "failures": _stats["failures"],
            "models": list(MODELS)}


@app.get("/models")
def models():
    return {"models": list(MODELS)}


@app.post("/decide")
def decide(request: DecideRequest):
    started = time.perf_counter()
    try:
        live = context(request.scenario)
        state = dict(request.state)
        # The caller sends `null` where a value is infinite (time to full of a stopped line).
        for section in state.get("sections", {}).values():
            if section.get("time_to_full_s") is None:
                section["time_to_full_s"] = math.inf
            if section.get("fault_remaining_s") is None:
                section["fault_remaining_s"] = 0.0
        live.update(**state)
        chosen = policy(request.model, request.scenario).decide(
            live.state(), live.legal_actions(), live)
        _stats["decisions"] += 1
        return {
            "action": str(chosen.action),
            "explanation": chosen.explanation,
            "scores": json_safe(chosen.scores),
            "model": request.model,
            "latency_ms": round((time.perf_counter() - started) * 1000.0, 2),
        }
    except Exception as exc:                                         # noqa: BLE001
        # A failing model must not take the robot down with it: report the failure and let the
        # executor use its fallback.
        _stats["failures"] += 1
        return {"error": f"{type(exc).__name__}: {exc}", "traceback": traceback.format_exc(),
                "model": request.model,
                "latency_ms": round((time.perf_counter() - started) * 1000.0, 2)}


def main():
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=int(os.environ.get("ROBOFETCH_AI_PORT", 8001)))


if __name__ == "__main__":
    main()

"""Robot actions and their predicted cost — pure Python, no ROS.

The action vocabulary is shared by everything that decides or executes: the scripted plans used
for testing, the fast simulator, the AI models and the live mission executor.

    PICKUP <section>   drive to A/B/C, load for load_time_s, take as many units as still fit
    DELIVER            drive to the delivery point, unload for unload_time_s
    CHARGE <percent>   drive to the charger and charge until the battery reaches <percent>
    WAIT <seconds>     stay where the robot is; waiting AT the charger means charging

`predict()` returns what an action should cost from the robot's current state using the same
robot_model equations and the generated maze path lengths, so predicted and measured values can
be compared for every executed action.
"""
from dataclasses import dataclass, field

from robofetch_core.robot_model import (battery_percent_for, charge_time_s, drive_energy_wh,
                                        idle_energy_wh, net_charge_power_w, travel_time_s)

PICKUP, DELIVER, CHARGE, WAIT = "PICKUP", "DELIVER", "CHARGE", "WAIT"
SECTIONS = ("A", "B", "C")
DELIVERY, CHARGER = "delivery", "charger"


@dataclass(frozen=True)
class Action:
    kind: str
    target: str = ""          # section for PICKUP
    value: float = 0.0        # battery % for CHARGE, seconds for WAIT

    def destination(self):
        return {PICKUP: self.target, DELIVER: DELIVERY, CHARGE: CHARGER}.get(self.kind)

    def __str__(self):
        if self.kind == PICKUP:
            return f"PICKUP:{self.target}"
        if self.kind in (CHARGE, WAIT):
            return f"{self.kind}:{self.value:g}"
        return self.kind


def parse_action(text):
    parts = [p.strip() for p in text.strip().replace(" ", ":", 1).split(":") if p.strip()]
    if not parts:
        raise ValueError("empty action")
    kind = parts[0].upper()
    if kind == PICKUP:
        if len(parts) != 2 or parts[1].upper() not in SECTIONS:
            raise ValueError(f"PICKUP needs a section {SECTIONS}: '{text}'")
        return Action(PICKUP, parts[1].upper())
    if kind == DELIVER:
        if len(parts) != 1:
            raise ValueError(f"DELIVER takes no argument: '{text}'")
        return Action(DELIVER)
    if kind == CHARGE:
        target = float(parts[1]) if len(parts) > 1 else 100.0
        if not 0.0 < target <= 100.0:
            raise ValueError(f"CHARGE target must be in (0, 100]: '{text}'")
        return Action(CHARGE, value=target)
    if kind == WAIT:
        if len(parts) != 2 or float(parts[1]) <= 0.0:
            raise ValueError(f"WAIT needs a positive number of seconds: '{text}'")
        return Action(WAIT, value=float(parts[1]))
    raise ValueError(f"unknown action '{text}' (PICKUP, DELIVER, CHARGE, WAIT)")


def parse_plan(text):
    """'PICKUP:B; PICKUP:A; DELIVER; CHARGE:90; WAIT:60' -> [Action, ...]"""
    return [parse_action(item) for item in text.split(";") if item.strip()]


@dataclass
class Prediction:
    distance_m: float
    duration_s: float
    energy_wh: float          # drawn from the battery
    charged_wh: float = 0.0
    battery_end_percent: float = 0.0
    notes: list = field(default_factory=list)


def predict(p, matrix, action, location, battery_percent, payload_kg,
            temperature_c=25.0, condition_percent=100.0):
    """Expected cost of `action` for a robot at `location` (a POI name)."""
    dest = action.destination()
    distance = matrix[location][dest] if dest else 0.0
    drive_s = travel_time_s(p, distance)
    energy = (drive_energy_wh(p, distance, payload_kg, temperature_c, condition_percent)
              + idle_energy_wh(p, drive_s))
    battery = battery_percent - battery_percent_for(p, energy)
    duration = drive_s
    charged = 0.0

    if action.kind == PICKUP:
        duration += p.load_time_s
        energy += idle_energy_wh(p, p.load_time_s)
        battery -= battery_percent_for(p, idle_energy_wh(p, p.load_time_s))
    elif action.kind == DELIVER:
        duration += p.unload_time_s
        energy += idle_energy_wh(p, p.unload_time_s)
        battery -= battery_percent_for(p, idle_energy_wh(p, p.unload_time_s))
    elif action.kind == CHARGE:
        target = max(battery, action.value)
        duration += charge_time_s(p, battery, target)
        charged = (target - battery) / 100.0 * p.capacity_wh
        battery = target
    elif action.kind == WAIT:
        duration += action.value
        if location == CHARGER:
            charged = min(net_charge_power_w(p) * action.value / 3600.0,
                          (100.0 - battery) / 100.0 * p.capacity_wh)
            battery += battery_percent_for(p, charged)
        else:
            idle = idle_energy_wh(p, action.value)
            energy += idle
            battery -= battery_percent_for(p, idle)
    return Prediction(distance, duration, energy, charged, max(0.0, battery))

