import os, statistics
from robofetch_ai.env.factory_sim import run_episode
from robofetch_ai.policies.base import Policy, Decision
from robofetch_core import fallback_policy
class FB(Policy):
  name='fallback'
  def decide(self, state, legal, sim=None):
    a, why = fallback_policy.decide(state, sim.p, sim.charge_targets(), 60.0)
    if str(a) not in {str(x) for x in legal}:
      return Decision([x for x in legal if x.kind=='WAIT'][0], 'illegal '+str(a))
    return Decision(a, why)
scs=sorted(f[:-5] for f in os.listdir('src/robofetch_factory/config/scenarios'))
for sc in scs:
  r=[run_episode(FB(),sc,s)[0] for s in range(10)]
